      SUBROUTINE DEFINECC     KEEPS TRACK OF DEFINED SECTIONS (24. ELEMENT)CC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA1C.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0F.CIN'      INCLUDE 'ELM24A.CIN'      INCLUDE 'ELM24B.CIN'      INCLUDE 'ELM24C.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'IOUNIT.CIN'CC     LOCAL VARIABLES      INTEGER  JCC------------------------------------------------------------------------      J = JDEF      GO TO (100,200,300,300), JCC     BEGINNING OF DEFINED SECTIONC  100 IF (.NOT. ATWORK) GO TO 400      IF (NDLEV .EQ. 0) GO TO 400      IF (LABEL(NUM) .EQ. NDN(NDLEV)) GO TO 250      GO TO 400CC     END OF DEFINED SECTIONC  200 IF (.NOT. ATWORK) GO TO 400      IF (NDLEV .EQ. 0) GO TO 400      IF (LABEL(NUM) .EQ. NDN(NDLEV)) GO TO 250      GO TO 400CC     EXIT FROM DEFINED SECTIONC  250 NUM = NDC(NDLEV)      NDIF = NDIF*NDS(NDLEV)      NDLEV = NDLEV - 1      IF (NDLEV .LT. 0 .OR. NDLEV .GT. 10) THEN        WRITE (NOUT,9002) NDLEV        FLUSHL = .TRUE.      ENDIF      GO TO 400CC     ENTER DEFINED SECTIONC  300 IF (NUM .EQ. NUSE) ATWORK = .TRUE.      IF (.NOT. ATWORK) GO TO 400      NDLEV = NDLEV + 1      IF (NDLEV .LE. 0 .OR. NDLEV .GT. 10) THEN        WRITE (NOUT,9002) NDLEV 9002   FORMAT (' *** ERROR *** BEAMLINE NESTING LEVEL = ',I5)        FLUSHL = .TRUE.        GO TO 400      ENDIF      NDC(NDLEV) = NUM      IF (J .EQ. 3) NDS(NDLEV) = 1      IF (J .EQ. 4) NDS(NDLEV) = -1      NDN(NDLEV) = LABEL(NUM)      NDIF = NDIF*NDS(NDLEV)      IF (NDIF .EQ. 1) NUM = NADDEF(1)      IF (NDIF .EQ. -1) NUM = NADDEF(2)C  400 CONTINUE      RETURN      END